def count_words(text):
    return len(text.split())

def wrap_fixed(text, width):
    lines = []
    cur = ""
    for w in text.split():
        if cur == "":
            # First word always goes on the line
            cur = w
        else:
            extra = len(w) + 1
            if len(cur) + extra > width:
                lines.append(cur)
                cur = w
            else:
                cur = f"{cur} {w}"
    if cur:
        lines.append(cur)
    return lines

# All original tests
tests = [
    ("a b", 5, ["a b"]),
    ("aaa bbb ccc", 7, ["aaa bbb", "ccc"]),
    ("one two three four", 9, ["one two", "three", "four"]),
    ("", 5, []),
]

for text, width, expected in tests:
    result = wrap_fixed(text, width)
    status = "PASS" if result == expected else "FAIL"
    print(f"{status}: wrap({repr(text)}, {width}) = {result}, expected {expected}")
